import { readFileSync, writeFileSync } from "node:fs";
import { recipeStandards, newRecipeIngredients } from "./standards.ts";
const q = (s: string) => "'" + s.replaceAll("'", "''") + "'";
const data = JSON.stringify(recipeStandards);
let sql = `-- Reviewed current-menu portions. No stock, accepted order requirements or financial history is rewritten.
-- Generated by scripts/recipes/build-migration.ts from standards.ts.
DO $recipes$
DECLARE product jsonb; portion jsonb; ingredient uuid;
BEGIN
`;
for (const i of newRecipeIngredients)
  sql += ` INSERT INTO ingredients(name,unit,current_stock,min_stock_alert,cost_per_unit,pack_size) SELECT ${q(i.name)},${q(i.unit)},0,${i.min_stock_alert},0,${i.pack_size} WHERE NOT EXISTS(SELECT 1 FROM ingredients WHERE name=${q(i.name)});
`;
sql += ` FOR product IN SELECT value FROM jsonb_array_elements(${q(data)}::jsonb) LOOP
  IF NOT EXISTS(SELECT 1 FROM menu_items WHERE id=(product->>'id')::uuid AND name=product->>'name') THEN CONTINUE; END IF;
  DELETE FROM menu_item_ingredients WHERE menu_item_id=(product->>'id')::uuid;
  FOR portion IN SELECT value FROM jsonb_array_elements(product->'portions') LOOP
   SELECT id INTO ingredient FROM ingredients WHERE name=portion->>'ingredient';
   IF ingredient IS NULL THEN RAISE EXCEPTION 'Missing recipe ingredient: %',portion->>'ingredient'; END IF;
   INSERT INTO menu_item_ingredients(menu_item_id,ingredient_id,quantity_used,size_multipliers)
   VALUES((product->>'id')::uuid,ingredient,(portion->>'quantity')::numeric,portion->'sizes');
  END LOOP;
  IF product->>'category'='Refreshers' AND NOT EXISTS(SELECT 1 FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='size') THEN
   INSERT INTO item_variants(menu_item_id,variant_group,label,price_modifier,is_default,sort_order) VALUES((product->>'id')::uuid,'size','Medium 16oz',0,true,0);
  END IF;
  IF (product->>'icedOnly')::boolean THEN
   DELETE FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='temperature' AND label='Hot';
   DELETE FROM item_variants WHERE menu_item_id=(product->>'id')::uuid AND variant_group='size' AND label='Hot 12oz';
  END IF;
 END LOOP;
END $recipes$;
-- The size mappings supply exactly one cup/lid/straw. Hot drinks use the existing hot lid stock.
INSERT INTO variant_ingredients(variant_group,variant_label,ingredient_id,quantity_used)
SELECT 'size','Hot 12oz',i.id,1 FROM ingredients i WHERE i.name='Lid'
AND NOT EXISTS(SELECT 1 FROM variant_ingredients v WHERE v.variant_group='size' AND v.variant_label='Hot 12oz' AND v.ingredient_id=i.id);
-- Flavored fries must actually consume the selected seasoning.
INSERT INTO variant_ingredients(variant_group,variant_label,ingredient_id,quantity_used)
SELECT 'flavor',x.label,i.id,5 FROM (VALUES ('Cheese','Cheese Seasoning'),('Sour Cream','Sour Cream Seasoning'),('BBQ','BBQ Seasoning')) x(label,ingredient)
JOIN ingredients i ON i.name=x.ingredient WHERE NOT EXISTS(SELECT 1 FROM variant_ingredients v WHERE v.variant_group='flavor' AND v.variant_label=x.label AND v.ingredient_id=i.id);
-- Dry pearls are measured before cooking. Melted chocolate chips supply the drizzle.
UPDATE variant_ingredients SET quantity_used=20 WHERE variant_group='add_on' AND variant_label='Tapioca Pearls' AND ingredient_id IN(SELECT id FROM ingredients WHERE name='Tapioca Pearls (raw)');
UPDATE variant_ingredients SET ingredient_id=(SELECT id FROM ingredients WHERE name='Chocolate Chips') WHERE variant_group='add_on' AND variant_label='Chocolate Drizzle' AND ingredient_id IN(SELECT id FROM ingredients WHERE name='Chocolate Powder') AND EXISTS(SELECT 1 FROM ingredients WHERE name='Chocolate Chips');

CREATE OR REPLACE FUNCTION public.inv_requirements(p_item uuid,p_variants jsonb DEFAULT '[]',p_quantity numeric DEFAULT 1)
RETURNS TABLE(ingredient_id uuid,quantity numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH size AS(SELECT COALESCE((SELECT v->>'label' FROM jsonb_array_elements(p_variants) v WHERE v->>'variant_group'='size' LIMIT 1),'Medium 16oz') label),
config AS(SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE (v->>'variant_group'='temperature' AND v->>'label'='Hot') OR (v->>'variant_group'='size' AND v->>'label'='Hot 12oz')) hot,
 EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE v->>'variant_group'='sugar_level' AND v->>'label'='Less Sweet') less_sweet),
selected AS(SELECT vi.* FROM variant_ingredients vi WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE v->>'label'=vi.variant_label AND v->>'variant_group'=vi.variant_group)),
base AS(SELECT m.ingredient_id,m.quantity_used*COALESCE((m.size_multipliers->>(SELECT label FROM size))::numeric,1) qty FROM menu_item_ingredients m
 WHERE m.menu_item_id=p_item AND NOT EXISTS(SELECT 1 FROM selected s WHERE s.replaces_ingredient_id=m.ingredient_id)),
extra AS(SELECT s.ingredient_id,s.quantity_used*COALESCE((s.size_multipliers->>(SELECT label FROM size))::numeric,
 (SELECT (r.size_multipliers->>(SELECT label FROM size))::numeric FROM menu_item_ingredients r WHERE r.menu_item_id=p_item AND r.ingredient_id=s.replaces_ingredient_id),1) qty FROM selected s
 WHERE NOT EXISTS(SELECT 1 FROM selected replacement WHERE replacement.replaces_ingredient_id=s.ingredient_id AND replacement.id<>s.id)),
combined AS(SELECT * FROM base UNION ALL SELECT * FROM extra)
SELECT c.ingredient_id,sum(c.qty*CASE WHEN config.less_sweet AND i.name IN ('Vanilla Syrup','French Vanilla Syrup','Caramel Syrup','Hazelnut Syrup','Macadamia Syrup','Butterscotch Syrup','White Mocha Sauce','Salted Caramel Sauce','Condensed Milk','Brown Sugar Syrup','Simple Syrup') THEN 0.5 ELSE 1 END)*p_quantity
FROM combined c JOIN ingredients i ON i.id=c.ingredient_id CROSS JOIN config
WHERE NOT(config.hot AND i.name='Ice') GROUP BY c.ingredient_id HAVING sum(c.qty)>0;
$$;
`;
// Keep the established exhaustive fallback and mandatory-ingredient pruning, but
// account for optional ice in hot drinks and the smaller Less Sweet dose.
let availability = readFileSync(
  "supabase/migrations/20261016001500_catalog_availability_scaling.sql",
  "utf8",
);
availability = availability.replace(
  "AND NOT EXISTS(SELECT 1 FROM variant_ingredients",
  `AND NOT (i.name='Ice' AND EXISTS(SELECT 1 FROM item_variants iv WHERE iv.menu_item_id=p_item AND ((iv.variant_group='size' AND iv.label='Hot 12oz') OR (iv.variant_group='temperature' AND iv.label='Hot'))))
  AND NOT EXISTS(SELECT 1 FROM variant_ingredients`,
);
availability = availability.replace(
  "<r.quantity_used*COALESCE(",
  `<r.quantity_used*CASE WHEN i.name IN ('Vanilla Syrup','French Vanilla Syrup','Caramel Syrup','Hazelnut Syrup','Macadamia Syrup','Butterscotch Syrup','White Mocha Sauce','Salted Caramel Sauce','Condensed Milk','Brown Sugar Syrup','Simple Syrup') AND EXISTS(SELECT 1 FROM item_variants iv WHERE iv.menu_item_id=p_item AND iv.variant_group='sugar_level' AND iv.label='Less Sweet') THEN 0.5 ELSE 1 END*COALESCE(`,
);
availability = availability.replace(
  "WHERE g.variant_group<>'size'",
  "WHERE g.variant_group='add_on'",
);
sql += "\n" + availability;
writeFileSync("supabase/migrations/20261018000100_recipe_realism.sql", sql);
console.log(
  JSON.stringify({
    products: recipeStandards.length,
    newUncountedIngredients: newRecipeIngredients.length,
  }),
);
